<?php
require __DIR__.'/../.besttop10-private/app/bootstrap.php';
require ROOT.'/app/layout.php';
header('Cache-Control: no-store');
header('X-Robots-Tag: noindex, nofollow');
$error='';$view=(string)($_GET['view']??'dashboard');
$logged=isset($_SESSION['admin']);
if($logged && time()-($_SESSION['active']??0)>3600){unset($_SESSION['admin']);$logged=false;}
if($logged)$_SESSION['active']=time();
if($_SERVER['REQUEST_METHOD']==='POST'){
 checkCsrf(); $action=(string)($_POST['action']??'');
 try {
  if($action==='login'){
   $ip=$_SERVER['REMOTE_ADDR']??'local';$attempt=query('SELECT * FROM login_attempts WHERE ip=?',[$ip])[0]??null;
   if($attempt && (int)$attempt['attempts']>=5 && time()-(int)$attempt['last_at']<900)throw new RuntimeException('Too many attempts. Please try again in 15 minutes.');
   $user=query('SELECT * FROM admins WHERE email=?',[strtolower(trim((string)($_POST['email']??'')))])[0]??null;
   if(!$user||!password_verify((string)($_POST['password']??''),$user['password'])){
    $count=$attempt&&time()-(int)$attempt['last_at']<900?(int)$attempt['attempts']+1:1;
    run('INSERT INTO login_attempts(ip,attempts,last_at) VALUES (?,?,?) ON CONFLICT(ip) DO UPDATE SET attempts=excluded.attempts,last_at=excluded.last_at',[$ip,$count,time()]);
    throw new RuntimeException('Email or password is incorrect.');
   }
   run('DELETE FROM login_attempts WHERE ip=?',[$ip]);session_regenerate_id(true);$_SESSION['admin']=$user['id'];$_SESSION['active']=time();$_SESSION['csrf']=bin2hex(random_bytes(32));redirect('/admin.php');
  }
  if(!$logged){http_response_code(403);throw new RuntimeException('Please sign in.');}
  if($action==='logout'){$_SESSION=[];session_destroy();redirect('/admin.php');}
  if($action==='save_review'){
   $id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));$category=(int)($_POST['category_id']??0);$score=filter_var($_POST['score']??'',FILTER_VALIDATE_FLOAT);
   if($title===''||mbLength($title)>200)throw new RuntimeException('Enter a title of 1–200 characters.');
   if(!query('SELECT id FROM categories WHERE id=?',[$category]))throw new RuntimeException('Choose a valid category.');
   if($score===false||$score<0||$score>10)throw new RuntimeException('Score must be between 0 and 10.');
   $data=[];foreach(['excerpt','body','image','pros','cons','verdict','author'] as $key){$data[$key]=trim((string)($_POST[$key]??''));if(!in_array($key,['image','pros','cons','verdict'],true)&&$data[$key]==='')throw new RuntimeException('Please complete all review fields.');}
   $upload=$_FILES['image_upload']??null;
   $hasUpload=$upload&&($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE;
   if(!$hasUpload&&!safeImage($data['image']))throw new RuntimeException('Image must be an HTTPS URL or a local image path.');
   $slug=slug(trim((string)($_POST['slug']??''))?:$title);
   if(query('SELECT id FROM reviews WHERE slug=? AND id!=?',[$slug,$id]))throw new RuntimeException('This URL slug is already used. Choose another.');
   if($hasUpload){
    if($upload['error']!==UPLOAD_ERR_OK||$upload['size']>5*1024*1024)throw new RuntimeException('Upload a JPG, PNG or WebP image under 5 MB.');
    $info=@getimagesize($upload['tmp_name']);$extensions=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
    if(!$info||!isset($extensions[$info['mime']])||$info[0]>10000||$info[1]>10000)throw new RuntimeException('Choose a valid JPG, PNG or WebP image, up to 10,000 pixels per side.');
    $folder=ROOT.'/public/uploads';if(!is_dir($folder)&&!mkdir($folder,0755,true))throw new RuntimeException('Image storage is unavailable.');
    $file=bin2hex(random_bytes(16)).'.'.$extensions[$info['mime']];
    if(!move_uploaded_file($upload['tmp_name'],$folder.'/'.$file))throw new RuntimeException('The image could not be saved.');
    $data['image']='/uploads/'.$file;
   }
   $values=[$category,$title,$slug,$data['excerpt'],$data['body'],$data['image'],$score,$data['pros'],$data['cons'],$data['verdict'],$data['author'],($_POST['status']??'draft')==='published'?'published':'draft',isset($_POST['featured'])?1:0,isset($_POST['demo'])?1:0,date('c')];
   if($id){if(!query('SELECT id FROM reviews WHERE id=?',[$id]))throw new RuntimeException('Review not found.');$values[]=$id;run('UPDATE reviews SET category_id=?,title=?,slug=?,excerpt=?,body=?,image=?,score=?,pros=?,cons=?,verdict=?,author=?,status=?,featured=?,demo=?,updated_at=? WHERE id=?',$values);}
   else{$values[]=date('c');run('INSERT INTO reviews(category_id,title,slug,excerpt,body,image,score,pros,cons,verdict,author,status,featured,demo,updated_at,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',$values);}
   $_SESSION['flash']='Review saved.';redirect('/admin.php?view=reviews');
  }
  if($action==='delete_review'){run('DELETE FROM reviews WHERE id=?',[(int)($_POST['id']??0)]);$_SESSION['flash']='Review deleted.';redirect('/admin.php?view=reviews');}
  if($action==='save_category'){
   $name=trim((string)($_POST['name']??''));$id=(int)($_POST['id']??0);if($name===''||mbLength($name)>60)throw new RuntimeException('Category name must be 1–60 characters.');$slug=slug($name);
   if(query('SELECT id FROM categories WHERE slug=? AND id!=?',[$slug,$id]))throw new RuntimeException('A category with this name already exists.');
   $icon=(string)($_POST['icon']??'grid');if(!in_array($icon,['tech','shopping','travel','gadgets','home','grid'],true))$icon='grid';
   if($id)run('UPDATE categories SET name=?,slug=?,icon=? WHERE id=?',[$name,$slug,$icon,$id]);else run('INSERT INTO categories(name,slug,icon) VALUES (?,?,?)',[$name,$slug,$icon]);
   $_SESSION['flash']='Category saved.';redirect('/admin.php?view=categories');
  }
  if($action==='delete_category'){
   $id=(int)($_POST['id']??0);if(query('SELECT id FROM reviews WHERE category_id=? LIMIT 1',[$id]))throw new RuntimeException('Move or delete this category’s reviews first, including drafts.');run('DELETE FROM categories WHERE id=?',[$id]);$_SESSION['flash']='Category deleted.';redirect('/admin.php?view=categories');
  }
  if($action==='settings'){
   foreach(['site_name','tagline','description'] as $k){$value=trim((string)($_POST[$k]??''));if($value===''||strlen($value)>500)throw new RuntimeException('Complete all settings (maximum 500 characters each).');}
   foreach(['site_name','tagline','description'] as $k)run('INSERT INTO settings(key,value) VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',[$k,trim($_POST[$k])]);
   $_SESSION['flash']='Website settings updated.';redirect('/admin.php?view=settings');
  }
  if($action==='password'){
   $user=query('SELECT * FROM admins WHERE id=?',[$_SESSION['admin']])[0];
   if(!password_verify((string)($_POST['current_password']??''),$user['password']))throw new RuntimeException('Current password is incorrect.');
   $password=(string)($_POST['new_password']??'');if(strlen($password)<12)throw new RuntimeException('Use at least 12 characters.');
   run('UPDATE admins SET password=? WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$user['id']]);session_regenerate_id(true);$_SESSION['flash']='Password updated.';redirect('/admin.php?view=settings');
  }
 }catch(RuntimeException $ex){$error=$ex->getMessage();}catch(Throwable $ex){error_log((string)$ex);$error='Unable to save. Please check the fields and try again.';}
}
function mbLength(string $s): int {return strlen($s);}
headerView('Editorial CMS');
